const html = $json.body || '';

// If the site explicitly says "Keine Angebote", short-circuit quickly.
const noOffers = /Keine\s+Angebote/i.test(html);

// Offer pages are typically linked under the same path with an extra segment.
// We extract ONLY links like /wohnen/aktuelle-wohnangebote/<something>
// and ignore the base listing URL.
const base = 'https://www.stwdo.de';

const linkRegex = /href\s*=\s*"(\/wohnen\/aktuelle-wohnangebote\/[^"]+)"/gi;
const links = new Set();
let m;
while ((m = linkRegex.exec(html)) !== null) {
  const path = m[1];
  // Guard: ignore any accidental repeats of the listing URL
  if (path === '/wohnen/aktuelle-wohnangebote') continue;
  // Some sites include anchors with trailing quotes or query params; keep full path
  links.add(base + path);
}

// Attempt to also extract a title near each link (best-effort).
// We'll do a simple approach: find the <a ...href="...">TEXT</a>
const offers = [];
for (const url of links) {
  const path = url.replace(base, '');
  const aTag = new RegExp(`<a[^>]*href=\\"${path.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&')}\\"[^>]*>([\\s\\S]*?)<\\/a>`, 'i');
  const aMatch = html.match(aTag);
  let title = '';
  if (aMatch && aMatch[1]) {
    title = aMatch[1]
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
  }
  offers.push({ url, title: title || 'STWDO Wohnangebot' });
}

return [
  {
    json: {
      noOffers,
      count: offers.length,
      offers
    }
  }
];

const data = getWorkflowStaticData('global');

// Keep a set of seen URLs
if (!data.seenUrls) data.seenUrls = {};

const offers = $json.offers || [];
const newOnes = [];

for (const o of offers) {
  if (!o || !o.url) continue;
  if (!data.seenUrls[o.url]) {
    newOnes.push(o);
    data.seenUrls[o.url] = new Date().toISOString();
  }
}

// Optional: prevent unbounded growth (keep last ~500 URLs)
const keys = Object.keys(data.seenUrls);
if (keys.length > 500) {
  // delete oldest entries
  const sorted = keys
    .map(k => ({ k, t: data.seenUrls[k] }))
    .sort((a,b) => (a.t < b.t ? -1 : 1));
  const toDelete = sorted.slice(0, keys.length - 500);
  for (const item of toDelete) delete data.seenUrls[item.k];
}

return [
  {
    json: {
      newCount: newOnes.length,
      newOffers: newOnes
    }
  }
];

